ont-size: 16px;\\n  font-weight: bold;\\n  text-box-trim: none;\\n}\\n.button:active {\\n  transform: none;\\n}\\n\\nimg {\\n  max-width: 100%;\\n  height: auto;\\n}\\n\\na, a:link, a:visited, a:active, a:hover {\\n  text-decoration: underline;\\n  color: blue;\\n}\\n\\n.email-data-table {\\n  width: 100%;\\n  border-collapse: collapse;\\n}\\n.email-data-table th, .email-data-table td {\\n  text-align: left;\\n  padding: 10px 10px 10px 0;\\n  border-bottom: 1px solid var(--color-border, var(--color-gray-2, #dcdcdc));\\n  vertical-align: middle;\\n}\\n.email-data-table th:last-child, .email-data-table td:last-child {\\n  text-align: right;\\n  padding-right: 0;\\n}\\n.email-data-table td.price {\\n  white-space: nowrap;\\n}\\n.email-data-table thead {\\n  font-weight: bold;\\n}\\n.email-data-table thead th {\\n  font-size: 10pt;\\n}\\n.email-data-table h4 ~ p {\\n  padding-top: 3px;\\n  opacity: 0.8;\\n  font-size: 11pt;\\n}\\n\\n.style-inline-code {\\n  font-family: monospace;\\n  white-space: pre-wrap;\\n  display: inline-block;\\n  letter-spacing: 1%;\\n}\\n\\n.style-code-large {\\n  font-family: monospace;\\n  white-space: pre-wrap;\\n  font-size: 16pt;\\n  letter-spacing: 2px;\\n  background: #f2f2f2;\\n  padding: 6px 10px;\\n  border-radius: 6px;\\n  display: inline-block;\\n}\\n\\n.email-style-description-small {\\n  font-size: 14px;\\n  line-height: 1.5;\\n  font-weight: normal;\\n  color: var(--color-gray-4, #5e5e5e);\\n  font-variation-settings: \\\"opsz\\\" 19;\\n}\\n\\n.email-style-title-list {\\n  font-size: 16px;\\n  line-height: 1.3;\\n  font-weight: 500;\\n}\\n.email-style-title-list + p {\\n  padding-top: 3px;\\n}\\n\\n.email-style-title-prefix-list {\\n  font-size: 11px;\\n  line-height: 1.5;\\n  font-weight: bold;\\n  color: {{primaryColor}};\\n  text-transform: uppercase;\\n  margin-bottom: 3px;\\n}\\n.email-style-title-prefix-list.error {\\n  color: #f0153d;\\n}\\n\\n.email-style-price-base, .email-style-discount-price, .email-style-discount-old-