n  font-size: 16px;\\n  line-height: 1.3;\\n  font-weight: 500;\\n}\\n.email-style-title-list + p {\\n  padding-top: 3px;\\n}\\n\\n.email-style-title-prefix-list {\\n  font-size: 11px;\\n  line-height: 1.5;\\n  font-weight: bold;\\n  color: {{primaryColor}};\\n  text-transform: uppercase;\\n  margin-bottom: 3px;\\n}\\n.email-style-title-prefix-list.error {\\n  color: #f0153d;\\n}\\n\\n.email-style-price-base, .email-style-discount-price, .email-style-discount-old-price, .email-style-price {\\n  font-size: 15px;\\n  line-height: 1.4;\\n  font-weight: 500;\\n  font-variant-numeric: tabular-nums;\\n}\\n.email-style-price-base.disabled, .disabled.email-style-discount-price, .disabled.email-style-discount-old-price, .disabled.email-style-price {\\n  opacity: 0.6;\\n}\\n.email-style-price-base.negative, .negative.email-style-discount-price, .negative.email-style-discount-old-price, .negative.email-style-price {\\n  color: #f0153d;\\n}\\n\\n.email-style-price {\\n  font-weight: bold;\\n  color: {{primaryColor}};\\n}\\n\\n.email-style-discount-old-price {\\n  text-decoration: line-through;\\n  color: var(--color-gray-4, #5e5e5e);\\n}\\n\\n.email-style-discount-price {\\n  font-weight: bold;\\n  color: #ff4747;\\n  margin-left: 5px;\\n}\\n\\n.pre-wrap {\\n  white-space: pre-wrap;\\n} hr {height: 2px;background: #e7e7e7; border-radius: 1px; padding: 0; margin: 20px 0; outline: none; border: 0;} .button.primary { margin: 0; text-decoration: none; font-size: 16px; font-weight: bold; color: {{primaryColorContrast}}; padding: 0 27px; line-height: 42px; background: {{primaryColor}}; text-align: center; border-radius: 7px; touch-action: manipulation; display: inline-block; transition: 0.2s transform, 0.2s opacity; } .button.primary:active { transform: scale(0.95, 0.95); }  .inline-link, .inline-link:link, .inline-link:visited, .inline-link:active, .inline-link:hover { margin: 0; text-decoration: underline; font-size: inherit; font-weight: inherit; color: inherit; touch-action: manipulation; } .inline-link:active { opacity: 0.5; }  .description { color: #5e5e5e; } </style>\\n</head>\\n\\n<body>\\n<p style=\\\"margin: 0; padding: 0; line-height: 1.4;\\\">{{greeting}}</p><p style=\\\"margin: 0; padding: 0; line-height: 1.4;\\\"><br></p><p style=\\\"margin: 0; padding: 0; line-height: 1.4;\\\"><br></p><p style=\\\"margin: 0; padding: 0; line-height: 1.4;\\\">Kind regards,</p><p style=\\\"margin: 0; padding: 0; line-height: 1.4;\\\">{{organizationName}}</p><div class=\\\"email-only\\\"><hr style=\\\"height: 2px;background: #e7e7e7; border-radius: 1px; padding: 0; margin: 20px 0; outline: none; border: 0;\\\"><div data-type=\\\"smartButton\\\" data-id=\\\"signInUrl\\\"><table width=\\\"100%\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"margin: 5px 0;\\\">\\n<tbody><tr>\\n    <td>\\n        <table cellspacing=\\\"0\\\" cellpadding=\\\"0\\\">\\n            <tbody><tr>\\n                <td style=\\\"border-radius: 7px;\\\" bgcolor=\\\"{{primaryColor}}\\\">\\n                <a class=\\\"button primary\\\" href=\\\"{{signInUrl}}\\\" target=\\\"\\\" style=\\\"margin: 0; text-decoration: none; font-size: 16px; font-weight: bold; color: {{primaryColorContrast}}; padding: 0 27px; line-height: 42px; background: {{primaryColor}}; text-align: center; border-radius: 7px; touch-action: manipulation; display: inline-block; transition: 0.2s transform, 0.2s opacity;\\\">Open member portal</a>\\n                </td>\\n            </tr>\\n        </tbody></table>\\n    </td>\\n</tr>\\n</tbody></table></div><div data-type=\\\"smartVariableBlock\\\" data-id=\\\"loginDetails\\\">{{loginDetails}}</div><p style=\\\"margin: 0; padding: 0; line-height: 1.4;\\\"><br></p><hr style=\\\"height: 2px;background: #e7e7e7; border-radius: 1px; padding: 0; margin: 20px 0; outline: none; border: 0;\\\"><p class=\\\"description\\\" style=\\\"color: #5e5e5e;\\\">Do you no longer want to receive emails from {{organizationName}}? <a class=\\\"inline-link\\\" href=\\\"{{unsubscribeUrl}}\\\" target=\\\"\\\" style=\\\"margin: 0; text-decoration: underline; font-size: inherit; font-weight: inherit; color: inherit; touch-action: manipulation;\\\">Click here to unsubscribe</a>.</p></div>\\n</body>\\n\\n</html>\",\"text\":\"{{greeting}}\\n\\nKind regards,\\n{{organizationName}}\\n\\nOpen member portal ({{signInUrl}})\\n\\n{{loginDetails}}\\n\\nDo you no longer want to receive emails from {{organizationName}}? Click here to unsubscribe ({{unsubscribeUrl}}).\",\"json\":{\"type\":\"doc\",\"content\":[{\"type\":\"paragraph\",\"content\":[{\"type\":\"smartVariable\",\"attrs\":{\"id\":\"greeting\"}}]},{\"type\":\"paragraph\"},{\"type\":\"paragraph\"},{\"type\":\"paragraph\",\"content\":[{\"type\":\"text\",\"text\":\"Kind regards,\"}]},{\"type\":\"paragraph\",\"content\":[{\"type\":\"smartVariable\",\"attrs\":{\"id\":\"organizationName\"}}]},{\"type\":\"emailBlock\",\"content\":[{\"type\":\"horizontalRule\"},{\"type\":\"smartButton\",\"attrs\":{\"id\":\"signInUrl\"},\"content\":[{\"type\":\"text\",\"text\":\"Open member portal\"}]},{\"type\":\"smartVariableBlock\",\"attrs\":{\"id\":\"loginDetails\"}},{\"type\":\"paragraph\"},{\"type\":\"horizontalRule\"},{\"type\":\"descriptiveText\",\"content\":[{\"type\":\"text\",\"text\":\"Do you no longer want to receive emails from \"},{\"type\":\"smartVariable\",\"attrs\":{\"id\":\"organizationName\"}},{\"type\":\"text\",\"text\":\"? \"},{\"type\":\"smartButtonInline\",\"attrs\":{\"id\":\"unsubscribeUrl\"},\"content\":[{\"type\":\"text\",\"text\":\"Click here to unsubscribe\"}]},{\"type\":\"text\",\"text\":\".\"}]}]}]}}},\"version\":413}', 'nl'),
('f3bfa76e-f180-4f66-be5e-c667c0188fa7', 'Kopie betaalinstructies - {{overviewContext}}', NULL, NULL, NULL, 'RegistrationTransferDetails', 'Beste,Hierbij nog eens een kopie van de betaalinstructies voor de inschrijving van {{memberNames}}.Als je deze betaling al had uitgevoerd tijdens het inschrijven, kan je deze e-mail gewoon negeren en hoef je ons niet te contacteren.Je kan de betaalinstructies hieronder nog eens nakijken, en de status opvolgen via de knop onderaan.Met vriendelijke groeten,{{organizationName}}BetaalinstructiesVergeet zeker niet om de mededeling \'{{transferDescription}}\' te vermelden in jouw overschrijving, als je die nog niet zou hebben uitgevoerd.{{paymentTable}}Overzicht{{overviewTable}}Te betalen {{priceToPay}}\n\n    \n        \n            \n                \n                Open ledenportaal ({{signInUrl}})\n                \n            \n        \n    \n\n{{loginDetails}}Onze ledenadminstratie wordt mogelijk gemaakt door {{platformName}} (https://www.stamhoofd.be/ledenadministratie)', '<!DOCTYPE html>\n<html>\n\n<head>\n<meta charset=\"utf-8\" />\n<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\" />\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\" />\n<title>Kopie betaalinstructies - {{overviewContext}}</title>\n<style type=\"text/css\">body {\n  color: #000716;\n  color: var(--color-dark, #000716);\n  font-family: -apple-system-body, -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif, \"Apple Color Emoji\", \"Segoe UI Emoji\", \"Segoe UI Symbol\";\n  font-size: 12pt;\n  line-height: 1.4;\n}\n\np {\n  margin: 0;\n  padding: 0;\n  line-height: 1.4;\n}\n\np.description {\n  color: var(--color-gray-4, #5e5e5e);\n}\np.description a, p.description a:link, p.description a:visited, p.description a:active, p.description a:hover {\n  text-decoration: underline;\n  color: var(--color-gray-4, #5e5e5e);\n}\n\nstrong {\n  font-weight: bold;\n}\n\nem {\n  font-style: italic;\n}\n\nh1 {\n  font-size: 30px;\n  font-weight: bold;\n  line-height: 1.2;\n  margin: 0;\n  padding: 0;\n}\n@media (max-width: 350px) {\n  h1 {\n    font-size: 24px;\n  }\n}\n\nh2 {\n  font-size: 20px;\n  line-height: 1.2;\n  font-weight: bold;\n  margin: 0;\n  padding: 0;\n}\n\nh3 {\n  font-size: 16px;\n  line-height: 1.2;\n  font-weight: bold;\n  margin: 0;\n  padding: 0;\n}\n\nh4 {\n  line-height: 1.2;\n  font-weight: 500;\n  margin: 0;\n  padding: 0;\n}\n\nol, ul {\n  list-style-position: outside;\n  padding-left: 30px;\n}\n\nhr {\n  height: 1px;\n  background: var(--color-border, var(--color-gray-2, #dcdcdc));\n  border-radius: 1px;\n  padding: 0;\n  margin: 20px 0;\n  outline: none;\n  border: 0;\n}\n\n.button {\n  touch-action: inherit;\n  user-select: auto;\n  cursor: pointer;\n  display: inline-block !important;\n  line-height: 42px;\n  font-size: 16px;\n  font-weight: bold;\n}\n.button:active {\n  transform: none;\n}\n\nimg {\n  max-width: 100%;\n  height: auto;\n}\n\na, a:link, a:visited, a:active, a:hover {\n  text-decoration: underline;\n  color: blue;\n}\n\n.email-data-table {\n  width: 100%;\n  border-collapse: collapse;\n}\n.email-data-table th, .email-data-table td {\n  text-align: left;\n  padding: 10px 10px 10px 0;\n  border-bottom: 1px solid var(--color-border, var(--color-gray-2, #dcdcdc));\n  vertical-align: middle;\n}\n.email-data-table th:last-child, .email-data-table td:last-child {\n  text-align: right;\n  padding-right: 0;\n}\n.email-data-table thead {\n  font-weight: bold;\n}\n.email-data-table thead th {\n  font-size: 10pt;\n}\n.email-data-table h4 ~ p {\n  padding-top: 3px;\n  opacity: 0.8;\n  font-size: 11pt;\n}\n\n.email-style-inline-code {\n  font-family: monospace;\n  white-space: pre-wrap;\n  display: inline-block;\n}\n\n.email-style-description-small {\n  font-size: 14px;\n  line-height: 1.5;\n  font-weight: normal;\n  color: var(--color-gray-4, #5e5e5e);\n  font-variation-settings: \"opsz\" 19;\n}\n\n.email-style-title-list {\n  font-size: 16px;\n  line-height: 1.3;\n  font-weight: 500;\n}\n.email-style-title-list + p {\n  padding-top: 3px;\n}\n\n.email-style-title-prefix-list {\n  font-size: 11px;\n  line-height: 1.5;\n  font-weight: bold;\n  color: {{primaryColor}};\n  text-transform: uppercase;\n  margin-bottom: 3px;\n}\n.email-style-title-prefix-list.error {\n  color: #f0153d;\n}\n\n.email-style-price-base, .email-style-discount-price, .email-style-discount-old-price, .email-style-price {\n  font-size: 15px;\n  line-height: 1.4;\n  font-weight: 500;\n  font-variant-numeric: tabular-nums;\n}\n.email-style-price-base.disabled, .disabled.email-style-discount-price, .disabled.email-style-discount-old-price, .disabled.email-style-price {\n  opacity: 0.6;\n}\n.email-style-price-base.negative, .negative.email-style-discount-price, .negative.email-style-discount-old-price, .negative.email-style-price {\n  color: #f0153d;\n}\n\n.email-style-price {\n  font-weight: bold;\n  color: {{primaryColor}};\n}\n\n.email-style-discount-old-price {\n  text-decoration: line-through;\n  color: var(--color-gray-4, #5e5e5e);\n}\n\n.email-style-discount-price {\n  font-weight: bold;\n  color: #ff4747;\n  margin-left: 5px;\n}\n\n.pre-wrap {\n  white-space: pre-wrap;\n} hr {height: 2px;background: #e7e7e7; border-radius: 1px; padding: 0; margin: 20px 0; outline: none; border: 0;} .button.primary { margin: 0; text-decoration: none; font-size: 16px; font-weight: bold; color: {{primaryColorContrast}}; padding: 0 27px; line-height: 42px; background: {{primaryColor}}; text-align: center; border-radius: 7px; touch-action: manipulation; display: inline-block; transition: 0.2s transform, 0.2s opacity; } .button.primary:active { transform: scale(0.95, 0.95); }  .inline-link, .inline-link:link, .inline-link:visited, .inline-link:active, .inline-link:hover { margin: 0; text-decoration: underline; font-size: inherit; font-weight: inherit; color: inherit; touch-action: manipulation; } .inline-link:active { opacity: 0.5; }  .description { color: #5e5e5e; } </style>\n</head>\n\n<body>\n<p style=\"margin: 0; padding: 0; line-height: 1.4;\">Beste,</p><p style=\"margin: 0; padding: 0; line-height: 1.4;\"><br></p><p style=\"margin: 0; padding: 0; line-height: 1.4;\">Hierbij nog eens een kopie van de betaalinstructies voor de inschrijving van <strong>{{memberNames}}</strong>.</p><p style=\"margin: 0; padding: 0; line-height: 1.4;\"><br></p><p style=\"margin: 0; padding: 0; line-height: 1.4;\"><strong>Als je deze betaling al had uitgevoerd tijdens het inschrijven, kan je deze e-mail gewoon negeren en hoef je ons niet te contacteren.</strong></p><p style=\"margin: 0; padding: 0; line-height: 1.4;\"><br></p><p style=\"margin: 0; padding: 0; line-height: 1.4;\">Je kan de betaalinstructies hieronder nog eens nakijken, en de status opvolgen via de knop onderaan.</p><p style=\"margin: 0; padding: 0; line-height: 1.4;\"><br></p><p style=\"margin: 0; padding: 0; line-height: 1.4;\">Met vriendelijke groeten,</p><p style=\"margin: 0; padding: 0; line-height: 1.4;\">{{organizationName}}</p><p style=\"margin: 0; padding: 0; line-height: 1.4;\"><br></p><hr style=\"height: 2px;background: #e7e7e7; border-radius: 1px; padding: 0; margin: 20px 0; outline: none; border: 0;\"><h2 style=\"margin: 0; padding: 0;\">Betaalinstructies</h2><p style=\"margin: 0; padding: 0; line-height: 1.4;\"><br></p><p style=\"margin: 0; padding: 0; line-height: 1.4;\">Vergeet zeker niet om de mededeling \'{{transferDescription}}\' te vermelden in jouw overschrijving, als je die nog niet zou hebben uitgevoerd.</p><p style=\"margin: 0; padding: 0; line-height: 1.4;\"><br></p><div data-type=\"smartVariableBlock\" data-id=\"paymentTable\">{{paymentTable}}</div><p style=\"margin: 0; padding: 0; line-height: 1.4;\"><br></p><p style=\"margin: 0; padding: 0; line-height: 1.4;\"><br></p><h2 style=\"margin: 0; padding: 0;\">Overzicht</h2><h4 style=\"margin: 0; padding: 0;\"></h4><div data-type=\"smartVariableBlock\" data-id=\"overviewTable\">{{overviewTable}}</div><p style=\"margin: 0; padding: 0; line-height: 1.4;\"><br></p><h3 style=\"margin: 0; padding: 0;\">Te betalen {{priceToPay}}</h3><p style=\"margin: 0; padding: 0; line-height: 1.4;\"><br></p><hr style=\"height: 2px;background: #e7e7e7; border-radius: 1px; padding: 0; margin: 20px 0; outline: none; border: 0;\"><div data-type=\"smartButton\" data-id=\"signInUrl\"><table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"margin: 5px 0;\">\n<tbody><tr>\n    <td>\n        <table cellspacing=\"0\" cellpadding=\"0\">\n            <tbody><tr>\n                <td style=\"border-radius: 7px;\" bgcolor=\"{{primaryColor}}\">\n                <a class=\"button primary\" href=\"{{signInUrl}}\" target=\"\" style=\"margin: 0; text-decoration: none; font-size: 16px; font-weight: bold; color: {{primaryColorContrast}}; padding: 0 27px; line-height: 42px; background: {{primaryColor}}; text-align: center; border-radius: 7px; touch-action: manipulation; display: inline-block; transition: 0.2s transform, 0.2s opacity;\">Open ledenportaal</a>\n                </td>\n            </tr>\n        </tbody></table>\n    </td>\n</tr>\n</tbody></table></div><div data-type=\"smartVariableBlock\" data-id=\"loginDetails\">{{loginDetails}}</div><hr style=\"height: 2px;background: #e7e7e7; border-radius: 1px; padding: 0; margin: 20px 0; outline: none; border: 0;\"><p style=\"margin: 0; padding: 0; line-height: 1.4;\"><strong>Onze ledenadminstratie wordt mogelijk gemaakt door </strong><a target=\"_blank\" rel=\"noopener noreferrer nofollow\" href=\"https://www.stamhoofd.be/ledenadministratie\"><strong>{{platformName}}</strong></a></p><p style=\"margin: 0; padding: 0; line-height: 1.4;\"><br></p>\n</body>\n\n</html>', '{\"value\": {\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"text\": \"Beste,\", \"type\": \"text\"}]}, {\"type\": \"paragraph\"}, {\"type\": \"paragraph\", \"content\": [{\"text\": \"Hierbij nog eens een kopie van de betaalinstructies voor 